"""ML detector tests. ALL data here is synthetic (generated by OptimizedAnomalyDetector); results
say nothing about real-world attack detection accuracy."""
import contextlib, io, os, tempfile, unittest
import numpy as np
from models.optimized_models import OptimizedAnomalyDetector

NORMAL_CENTER = [4.5, 150, 200, 50, 10]  # session_duration, data_volume, api_calls, geo_distance, login_hour


class AnomalyDetectorTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.det = OptimizedAnomalyDetector()
        with contextlib.redirect_stdout(io.StringIO()):
            X, y = cls.det.generate_training_data(2000)
            result = cls.det.train(X, ["session_duration", "data_volume", "api_calls", "geo_distance", "login_hour"], y)
        assert result["status"] == "success", result

    def test_untrained_model_refuses_to_predict(self):
        with self.assertRaises(ValueError):
            OptimizedAnomalyDetector().predict(np.array([NORMAL_CENTER]))

    def test_rejects_malformed_input(self):
        for bad in (np.array(NORMAL_CENTER),                      # 1-D
                    np.array([[1.0, 2.0, 3.0]]),                  # wrong feature count
                    np.empty((0, 5)),                             # empty
                    np.array([[np.nan, 1, 1, 1, 1]]),             # NaN
                    np.array([[np.inf, 1, 1, 1, 1]])):            # inf
            with self.subTest(shape=bad.shape):
                with self.assertRaises(ValueError):
                    self.det.predict(bad)

    def test_output_shapes_and_labels(self):
        preds, scores = self.det.predict(np.array([NORMAL_CENTER, NORMAL_CENTER]))
        self.assertEqual(preds.shape, (2,)); self.assertEqual(scores.shape, (2,))
        self.assertTrue(set(preds.tolist()) <= {1, -1})
        self.assertTrue(np.isfinite(scores).all())

    def test_gross_outlier_scores_higher_than_typical_session(self):
        _, typical = self.det.predict(np.array([NORMAL_CENTER]))
        preds, extreme = self.det.predict(np.array([[40.0, 5000, 5000, 9000, 3]]))
        self.assertEqual(preds[0], -1)
        self.assertGreater(extreme[0], typical[0])

    def test_extreme_magnitudes_do_not_crash(self):
        preds, scores = self.det.predict(np.array([[1e12, 1e12, 1e12, 1e12, 1e12]]))
        self.assertEqual(preds[0], -1); self.assertTrue(np.isfinite(scores).all())

    def test_known_limitation_low_and_slow_activity_inside_baseline_is_not_flagged(self):
        """Evasion check: an attacker who keeps every feature inside the normal range is invisible to
        this per-session model. Documented limitation, asserted so a future change is noticed."""
        preds, _ = self.det.predict(np.array([[4.4, 148, 198, 49, 10]]))
        self.assertEqual(preds[0], 1)

    def test_prediction_is_deterministic(self):
        batch = np.array([NORMAL_CENTER, [12, 700, 900, 400, 3]])
        a = self.det.predict(batch); b = self.det.predict(batch)
        np.testing.assert_array_equal(a[0], b[0]); np.testing.assert_allclose(a[1], b[1])

    def test_save_load_roundtrip_matches(self):
        batch = np.array([NORMAL_CENTER, [12, 700, 900, 400, 3]])
        with tempfile.TemporaryDirectory() as d, contextlib.redirect_stdout(io.StringIO()):
            path = os.path.join(d, "m.joblib"); self.det.save(path)
            other = OptimizedAnomalyDetector(); other.load(path)
        np.testing.assert_allclose(self.det.predict(batch)[1], other.predict(batch)[1])


if __name__ == "__main__":
    unittest.main()
